const data = $json;

function decodePolyline(encoded) {
  if (!encoded || typeof encoded !== "string") {
    return [];
  }

  let index = 0;
  const len = encoded.length;
  let lat = 0;
  let lng = 0;
  const coordinates = [];

  while (index < len) {
    let b;
    let shift = 0;
    let result = 0;

    do {
      b = encoded.charCodeAt(index++) - 63;
      result |= (b & 0x1f) << shift;
      shift += 5;
    } while (b >= 0x20);

    const dlat = result & 1 ? ~(result >> 1) : result >> 1;
    lat += dlat;

    shift = 0;
    result = 0;

    do {
      b = encoded.charCodeAt(index++) - 63;
      result |= (b & 0x1f) << shift;
      shift += 5;
    } while (b >= 0x20);

    const dlng = result & 1 ? ~(result >> 1) : result >> 1;
    lng += dlng;

    coordinates.push([
      lng / 1e5,
      lat / 1e5
    ]);
  }

  return coordinates;
}

const routeLegs = Array.isArray(data.route_legs)
  ? data.route_legs
  : [];

const decodedRouteLegs = routeLegs.map(leg => {
  const existingGeometry = Array.isArray(leg.geometry)
    ? leg.geometry
    : [];

  const decodedGeometry =
    existingGeometry.length > 0
      ? existingGeometry
      : decodePolyline(leg.encoded_geometry);

  return {
    ...leg,
    geometry: decodedGeometry,
    geometry_source:
      existingGeometry.length > 0
        ? "existing_geometry"
        : leg.encoded_geometry
          ? "encoded_geometry"
          : "missing_geometry",
    geometry_point_count: decodedGeometry.length
  };
});

return [
  {
    json: {
      ...data,
      route_legs: decodedRouteLegs,
      debug_decode_geometry: {
        route_leg_count: decodedRouteLegs.length,
        route_leg_names: decodedRouteLegs.map(leg => leg.leg_name),
        geometry_point_counts: decodedRouteLegs.map(leg => ({
          leg_name: leg.leg_name,
          geometry_point_count: leg.geometry_point_count,
          geometry_source: leg.geometry_source
        }))
      }
    }
  }
];

const requestContext = $("BuildIntentInput").first().json;
const settings = requestContext.settings || {};
const vehicleSettings = settings.vehicle || {};
const familySettings = settings.family || {};

const householdId =
  requestContext.household_id ||
  requestContext.householdId ||
  settings.household?.household_id ||
  "prototype_household_1";

const activePersonId =
  requestContext.activePersonId ||
  requestContext.active_person_id ||
  "Parent1";

const vehicleId =
  requestContext.vehicle_id ||
  requestContext.vehicleId ||
  vehicleSettings.vehicle_id ||
  "shared_vehicle_1";

const fallbackHomeLocation = {
  label: "Home",
  address: "Macdonald Engineering Building, Montreal, QC, Canada",
  lat: 45.5049,
  lng: -73.5761
};

const homeLocationFromSettings = familySettings.home_location || {};

const homeLocation = {
  label:
    homeLocationFromSettings.label ||
    fallbackHomeLocation.label,

  address:
    homeLocationFromSettings.address ||
    fallbackHomeLocation.address,

  lat:
    Number.isFinite(Number(homeLocationFromSettings.lat))
      ? Number(homeLocationFromSettings.lat)
      : fallbackHomeLocation.lat,

  lng:
    Number.isFinite(Number(homeLocationFromSettings.lng))
      ? Number(homeLocationFromSettings.lng)
      : fallbackHomeLocation.lng
};

const allowCharging =
  vehicleSettings.allow_charging !== false;

const allowService =
  vehicleSettings.allow_service !== false;

const allowCarWash =
  vehicleSettings.allow_car_wash !== false;

const allowTireChange =
  vehicleSettings.allow_tire_change === true;

return [
  {
    json: {
      settings,

      household_id: householdId,
      householdId,

      activePersonId,
      active_person_id: activePersonId,

      vehicle_id: vehicleId,
      vehicleId,

      start_location: homeLocation,

      vehicle: {
        vehicle_id: vehicleId,

        enabled: vehicleSettings.enabled !== false,

        vehicle_type:
          vehicleSettings.vehicle_type || "electric_self_driving",

        shared_by_household: true,

        preferred_min_battery_percent:
          vehicleSettings.preferred_min_battery_percent ?? 60,

        critical_battery_percent:
          vehicleSettings.critical_battery_percent ?? 20,

        max_autonomous_tasks_per_day:
          vehicleSettings.max_autonomous_tasks_per_day ?? 2,

        home_location: homeLocation,

        return_home_after_day:
          vehicleSettings.return_home_after_day !== false,

        default_task_buffer_minutes:
          vehicleSettings.default_task_buffer_minutes ?? 10,

        service_operating_hours: {
          open: "08:00",
          close: "18:00"
        },

        charging_allowed_after_hours:
          vehicleSettings.charging_allowed_after_hours !== false,

        autonomous_tasks: [
          {
            type: "charging",
            title: "Vehicle Self-Charging",
            enabled: allowCharging,
            priority: 6,
            minimum_idle_minutes: 45,
            minimum_task_minutes: 20,
            default_duration_minutes: 30,
            can_run_during_user_event: true,
            respects_operating_hours: false,
            location: "Nearest available charging station",
            notes: "Optional autonomous EV charging stop."
          },
          {
            type: "service",
            title: "Vehicle Self-Service",
            enabled: allowService,
            priority: 7,
            minimum_idle_minutes: 90,
            minimum_task_minutes: 45,
            default_duration_minutes: 60,
            can_run_during_user_event: true,
            respects_operating_hours: true,
            location: "Preferred vehicle service center",
            notes: "Optional autonomous vehicle service stop."
          },
          {
            type: "tire_change",
            title: "Vehicle Tire Change",
            enabled: allowTireChange,
            priority: 8,
            minimum_idle_minutes: 120,
            minimum_task_minutes: 60,
            default_duration_minutes: 90,
            can_run_during_user_event: true,
            respects_operating_hours: true,
            location: "Preferred tire service center",
            notes: "Optional autonomous tire change stop."
          },
          {
            type: "car_wash",
            title: "Vehicle Car Wash",
            enabled: allowCarWash,
            priority: 9,
            minimum_idle_minutes: 60,
            minimum_task_minutes: 20,
            default_duration_minutes: 30,
            can_run_during_user_event: true,
            respects_operating_hours: true,
            location: "Nearest available car wash",
            notes: "Optional autonomous car wash stop."
          }
        ]
      }
    }
  }
];

const event = { ...$json };

const results =
  Array.isArray($json.results)
    ? $json.results
    : [];

delete event.results;
delete event.summary;

function numberOrNull(value) {
  if (value === null || value === undefined) {
    return null;
  }

  const text = String(value).trim();

  if (
    text === "" ||
    text.toLowerCase() === "null" ||
    text.toLowerCase() === "undefined"
  ) {
    return null;
  }

  const number = Number(text);

  return Number.isFinite(number)
    ? number
    : null;
}

function hasValidCoordinates(lat, lng) {
  return (
    lat !== null &&
    lng !== null &&
    lat >= -90 &&
    lat <= 90 &&
    lng >= -180 &&
    lng <= 180 &&
    !(lat === 0 && lng === 0)
  );
}

function normalize(value) {
  return String(value || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[’']/g, "")
    .replace(/[^a-z0-9 ]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function detectStreetDirection(value) {
  const tokens =
    new Set(normalize(value).split(" "));

  if (
    tokens.has("ouest") ||
    tokens.has("west") ||
    tokens.has("w") ||
    tokens.has("o")
  ) {
    return "west";
  }

  if (
    tokens.has("est") ||
    tokens.has("east") ||
    tokens.has("e")
  ) {
    return "east";
  }

  return null;
}

function extractStreetNumber(value) {
  const match =
    String(value || "")
      .trim()
      .match(/^(\d+)\b/);

  return match
    ? match[1]
    : null;
}

function looksLikeNamedPlace(value) {
  const text = normalize(value);

  return [
    "building",
    "engineering",
    "university",
    "college",
    "hospital",
    "clinic",
    "school",
    "campus",
    "chalet",
    "station",
    "airport",
    "hotel",
    "museum",
    "centre",
    "center"
  ].some(word => text.includes(word));
}

function resultAddress(result = {}) {
  return (
    result.address?.freeformAddress ||
    [
      result.address?.streetNumber,
      result.address?.streetName,
      result.address?.municipality
    ]
      .filter(Boolean)
      .join(" ")
  );
}

function resultPlaceName(result = {}) {
  return (
    result.poi?.name ||
    result.address?.building ||
    ""
  );
}

const requestedLocation =
  event.original_location ||
  event.resolved_location ||
  event.location ||
  "";

const requestedDirection =
  detectStreetDirection(requestedLocation);

const requestedStreetNumber =
  extractStreetNumber(requestedLocation);

const requestedNamedPlace =
  looksLikeNamedPlace(requestedLocation);

function evaluateResult(result, index) {
  /*
   * Fuzzy Search returns the relevance score directly
   * under result.score. The older Geocoding endpoint may
   * use matchConfidence.score, so keep it as a fallback.
   */
  const confidence =
    numberOrNull(
      result?.score ??
      result?.matchConfidence?.score
    ) ?? 0;

  const candidateAddress =
    resultAddress(result);

  const candidatePlaceName =
    resultPlaceName(result);

  const candidateDirection =
    detectStreetDirection(candidateAddress);

  const candidateStreetNumber =
    String(
      result?.address?.streetNumber || ""
    ).trim() || null;

  const resultType =
    String(result?.type || "");

  const directionMismatch =
    requestedDirection &&
    candidateDirection &&
    requestedDirection !== candidateDirection;

  const streetNumberMismatch =
    requestedStreetNumber &&
    candidateStreetNumber &&
    requestedStreetNumber !== candidateStreetNumber;

  const genericStreetForNamedPlace =
    requestedNamedPlace &&
    resultType === "Street" &&
    !candidatePlaceName;

  let rejectionReason = null;

  if (directionMismatch) {
    rejectionReason =
      `Requested ${requestedDirection}, but TomTom returned ${candidateDirection}.`;
  } else if (streetNumberMismatch) {
    rejectionReason =
      `Requested street number ${requestedStreetNumber}, but TomTom returned ${candidateStreetNumber}.`;
  } else if (genericStreetForNamedPlace) {
    rejectionReason =
      "Named place query returned only a generic street.";
  } else if (confidence < 0.75) {
    rejectionReason =
      `TomTom score ${confidence.toFixed(3)} is below 0.75.`;
  }

  let typeBonus = 0;

  if (requestedNamedPlace) {
    typeBonus = {
      POI: 50,
      "Point Address": 25,
      "Address Range": 15,
      Street: 0
    }[resultType] ?? 10;
  } else if (requestedStreetNumber) {
    typeBonus = {
      "Point Address": 50,
      "Address Range": 35,
      POI: 20,
      Street: 0
    }[resultType] ?? 10;
  } else {
    typeBonus = {
      POI: 35,
      "Point Address": 35,
      "Address Range": 25,
      Street: 10
    }[resultType] ?? 10;
  }

  const exactStreetNumberBonus =
    requestedStreetNumber &&
    candidateStreetNumber === requestedStreetNumber
      ? 20
      : 0;

  const directionMatchBonus =
    requestedDirection &&
    candidateDirection === requestedDirection
      ? 10
      : 0;

  const normalizedRequested =
    normalize(requestedLocation);

  const normalizedPlaceName =
    normalize(candidatePlaceName);

  const namedPlaceMatchBonus =
    requestedNamedPlace &&
    normalizedPlaceName &&
    (
      normalizedRequested.includes(normalizedPlaceName) ||
      normalizedPlaceName.includes(normalizedRequested)
    )
      ? 30
      : 0;

  const candidateScore =
    confidence * 100 +
    typeBonus +
    exactStreetNumberBonus +
    directionMatchBonus +
    namedPlaceMatchBonus;

  return {
    result,
    index,
    confidence,
    resultType,
    candidateAddress,
    candidatePlaceName,
    candidateScore,
    accepted:
      rejectionReason === null,
    rejectionReason
  };
}

const evaluatedResults =
  results.map(evaluateResult);

const acceptedResults =
  evaluatedResults
    .filter(candidate => candidate.accepted)
    .sort(
      (a, b) =>
        b.candidateScore -
        a.candidateScore
    );

const selectedCandidate =
  acceptedResults[0] || null;

const selectedResult =
  selectedCandidate?.result || null;

/*
 * Read saved coordinates as a fallback.
 * Some events have coordinates nested in family settings
 * rather than directly on the event.
 */
const familySettings =
  event.settings?.family || {};

const role =
  normalize(event.role);

const savedLocationPool =
  role === "dependent"
    ? familySettings.default_school_locations || []
    : familySettings.default_job_locations || [];

const savedPersonLocation =
  savedLocationPool.find(location =>
    normalize(location.person) ===
    normalize(event.person)
  ) || null;

const existingLat =
  numberOrNull(
    event.lat ??
    savedPersonLocation?.lat
  );

const existingLng =
  numberOrNull(
    event.lng ??
    savedPersonLocation?.lng
  );

const existingCoordinatesValid =
  hasValidCoordinates(
    existingLat,
    existingLng
  );

const mainEntryPoint =
  selectedResult?.entryPoints?.find(
    entry => entry.type === "main"
  )?.position || null;

const tomtomLat =
  numberOrNull(
    mainEntryPoint?.lat ??
    selectedResult?.position?.lat
  );

const tomtomLng =
  numberOrNull(
    mainEntryPoint?.lon ??
    selectedResult?.position?.lon
  );

const tomtomCoordinatesValid =
  hasValidCoordinates(
    tomtomLat,
    tomtomLng
  );

/*
 * Use TomTom first so the workflow remains TomTom-based.
 * Saved settings coordinates are only the fallback.
 */
const finalLat =
  tomtomCoordinatesValid
    ? tomtomLat
    : existingCoordinatesValid
      ? existingLat
      : null;

const finalLng =
  tomtomCoordinatesValid
    ? tomtomLng
    : existingCoordinatesValid
      ? existingLng
      : null;

let geocodingSource;
let geocodingStatus;

if (tomtomCoordinatesValid) {
  geocodingSource =
    "tomtom_fuzzy_search";

  geocodingStatus =
    "ok";
} else if (existingCoordinatesValid) {
  geocodingSource =
    "settings_coordinates";

  geocodingStatus =
    "ok_from_settings";
} else if (results.length > 0) {
  geocodingSource =
    "tomtom_rejected";

  geocodingStatus =
    "low_confidence_or_invalid_match";
} else {
  geocodingSource =
    "tomtom_no_results";

  geocodingStatus =
    "address_not_found";
}

const tomtomResolvedAddress =
  selectedCandidate?.candidateAddress ||
  "";

const tomtomPlaceName =
  selectedCandidate?.candidatePlaceName ||
  "";

return {
  json: {
    ...event,

    // Keep the calendar/settings name visible to the user.
    resolved_address:
      event.resolved_location ||
      event.original_location ||
      event.location ||
      tomtomPlaceName ||
      tomtomResolvedAddress,

    tomtom_resolved_address:
      tomtomResolvedAddress,

    tomtom_place_name:
      tomtomPlaceName,

    lat:
      finalLat,

    lng:
      finalLng,

    geocoding_source:
      geocodingSource,

    geocoding_status:
      geocodingStatus,

    location_resolution_status:
      hasValidCoordinates(finalLat, finalLng)
        ? "ok"
        : "geocoding_failed",

    geocoding_result_type:
      selectedCandidate?.resultType || null,

    geocoding_match_confidence:
      selectedCandidate?.confidence ?? null,

    geocoding_candidate_score:
      selectedCandidate?.candidateScore ?? null,

    geocoding_candidate_count:
      results.length,

    geocoding_rejected_results:
      evaluatedResults
        .filter(candidate => !candidate.accepted)
        .map(candidate => ({
          type:
            candidate.resultType,

          address:
            candidate.candidateAddress,

          place_name:
            candidate.candidatePlaceName,

          confidence:
            candidate.confidence,

          reason:
            candidate.rejectionReason
        }))
  }
};

const data = $json;

const start = data.start_location;
const events = Array.isArray(data.ordered_events)
  ? data.ordered_events
  : [];

const routeLegs = [];
const onsiteTransitions = [];

function numberOrNull(value) {
  if (value === null || value === undefined) return null;

  const text = String(value).trim();

  if (text === "") return null;
  if (text.toLowerCase() === "null") return null;
  if (text.toLowerCase() === "undefined") return null;

  const number = Number(text);

  return Number.isFinite(number) ? number : null;
}

function hasValidCoordinates(event = {}) {
  const lat = numberOrNull(event.lat);
  const lng = numberOrNull(event.lng);

  if (lat === null || lng === null) return false;

  // Protect against accidental null → 0 conversion.
  if (lat === 0 && lng === 0) return false;

  return true;
}

function sameCoordinates(a = {}, b = {}) {
  const aLat = numberOrNull(a.lat ?? a.start_lat);
  const aLng = numberOrNull(a.lng ?? a.start_lng);

  const bLat = numberOrNull(b.lat ?? b.end_lat);
  const bLng = numberOrNull(b.lng ?? b.end_lng);

  if (
    aLat === null ||
    aLng === null ||
    bLat === null ||
    bLng === null
  ) {
    return false;
  }

  // Small tolerance because geocoding can slightly shift coordinates.
  return (
    Math.abs(aLat - bLat) < 0.00005 &&
    Math.abs(aLng - bLng) < 0.00005
  );
}

function eventAddress(event = {}) {
  return (
    event.resolved_address ||
    event.resolved_location ||
    event.location ||
    ""
  );
}

function makeRouteLeg(fromEvent, toEvent) {
  return {
    leg_name: `${fromEvent.title} → ${toEvent.title}`,

    start_address: eventAddress(fromEvent),
    start_lat: fromEvent.lat,
    start_lng: fromEvent.lng,

    end_address: eventAddress(toEvent),
    end_lat: toEvent.lat,
    end_lng: toEvent.lng,

    start_event: fromEvent,
    destination_event: toEvent,

    mission_leg: true,

    route_visibility: {
      start_visible_to: fromEvent.visible_to || [],
      end_visible_to: toEvent.visible_to || [],
      start_summary_visible_to: fromEvent.summary_visible_to || [],
      end_summary_visible_to: toEvent.summary_visible_to || []
    },

    passengers_in_vehicle:
      toEvent.passengers_in_vehicle || [],

    destination_event_type:
      toEvent.event_type || toEvent.task_type || "",

    destination_vehicle_only:
      toEvent.vehicle_only === true ||
      toEvent.autonomous_vehicle_task === true,

    requires_tomtom_route: true
  };
}

function makeStartLeg(toEvent) {
  return {
    leg_name: `Start → ${toEvent.title}`,

    start_address: start.address,
    start_lat: start.lat,
    start_lng: start.lng,

    end_address: eventAddress(toEvent),
    end_lat: toEvent.lat,
    end_lng: toEvent.lng,

    start_event: {
      title: start.label || "Start",
      location: start.address,
      resolved_address: start.address,
      lat: start.lat,
      lng: start.lng,
      event_type: "start",
      task_type: "start",
      visible_to: toEvent.visible_to || [],
      summary_visible_to: toEvent.summary_visible_to || [],
      passengers_in_vehicle: toEvent.passengers_in_vehicle || []
    },

    destination_event: toEvent,

    mission_leg: true,

    route_visibility: {
      start_visible_to: toEvent.visible_to || [],
      end_visible_to: toEvent.visible_to || [],
      start_summary_visible_to: toEvent.summary_visible_to || [],
      end_summary_visible_to: toEvent.summary_visible_to || []
    },

    passengers_in_vehicle:
      toEvent.passengers_in_vehicle || [],

    destination_event_type:
      toEvent.event_type || toEvent.task_type || "",

    destination_vehicle_only:
      toEvent.vehicle_only === true ||
      toEvent.autonomous_vehicle_task === true,

    requires_tomtom_route: true
  };
}

const routableEvents = events
  .filter(hasValidCoordinates)
  .sort((a, b) => {
    const timeDiff = new Date(a.start) - new Date(b.start);

    if (timeDiff !== 0) {
      return timeDiff;
    }

    return Number(a.mission_step || 99) - Number(b.mission_step || 99);
  });

const unroutableEvents = events
  .filter(event => !hasValidCoordinates(event))
  .map(event => ({
    title: event.title,
    person: event.person,
    role: event.role,
    event_type: event.event_type || "",
    task_type: event.task_type || "",
    location: event.location || event.resolved_location || "",
    lat: event.lat ?? null,
    lng: event.lng ?? null,
    geocoding_source: event.geocoding_source || "",
    geocoding_status: event.geocoding_status || "",
    reason:
      Number(event.lat) === 0 && Number(event.lng) === 0
        ? "Invalid 0,0 coordinates"
        : "Missing valid coordinates"
  }));

if (routableEvents.length > 0) {
  routeLegs.push(
    makeStartLeg(routableEvents[0])
  );
}

let currentEvent = routableEvents[0] || null;

for (let i = 1; i < routableEvents.length; i++) {
  const nextEvent = routableEvents[i];

  if (!currentEvent) {
    currentEvent = nextEvent;
    continue;
  }

  if (sameCoordinates(currentEvent, nextEvent)) {
    onsiteTransitions.push({
      from: currentEvent.title,
      to: nextEvent.title,
      location: eventAddress(nextEvent),
      lat: nextEvent.lat,
      lng: nextEvent.lng,
      reason:
        "Both mission events are at the same location, so no driving route leg is needed."
    });

    // Important:
    // keep the later mission event as the current vehicle state.
    currentEvent = nextEvent;
    continue;
  }

  routeLegs.push(
    makeRouteLeg(currentEvent, nextEvent)
  );

  currentEvent = nextEvent;
}

return [
  {
    json: {
      start_location: start,

      ordered_events: events,
      routable_events: routableEvents,
      unroutable_events: unroutableEvents,

      onsite_transitions: onsiteTransitions,

      detected_conflicts:
        data.detected_conflicts || [],

      reschedule_recommendations:
        data.reschedule_recommendations || [],

      caregiver_assignments:
        data.caregiver_assignments || [],

      notes_for_route_planner:
        data.notes_for_route_planner || [],

      family_members:
        data.family_members || [],

      vehicle_status:
        data.vehicle_status || data.vehicle_dynamic || null,

      vehicle_dynamic:
        data.vehicle_dynamic || data.vehicle_status || null,

      charging_decision:
        data.charging_decision || null,

      autonomous_tasks_added:
        data.autonomous_tasks_added || 0,

      selected_charging_location:
        data.selected_charging_location || null,

      selected_charging_location_reason:
        data.selected_charging_location_reason || "",

      route_legs: routeLegs,

      debug_vehicle_mission_routing: true,

      debug_routable_event_titles:
        routableEvents.map(event => event.title),

      debug_unroutable_event_titles:
        unroutableEvents.map(event => event.title),

      debug_route_leg_names:
        routeLegs.map(leg => leg.leg_name),

      debug_onsite_transitions:
        onsiteTransitions
    }
  }
];

const route = $json.routes?.[0];

if (!route) {
  throw new Error(`TomTom routing failed for ${$json.leg_name || "route leg"}: no route returned.`);
}

const summary = route.summary || {};
const tomtomLegs = route.legs || [];
const guidance = route.guidance || {};
const instructions = guidance.instructions || [];

const destinationEvent = $json.destination_event || {};

const durationSeconds =
  summary.travelTimeInSeconds ?? null;

const distanceMeters =
  summary.lengthInMeters ?? null;

const noTrafficDurationSeconds =
  summary.noTrafficTravelTimeInSeconds ?? null;

const trafficDelaySeconds =
  summary.trafficDelayInSeconds ?? 0;

const trafficLengthMeters =
  summary.trafficLengthInMeters ?? 0;

// Convert TomTom points into the same geometry format
// your construction workflow already expects: [lng, lat]
const geometry = tomtomLegs.flatMap(leg =>
  (leg.points || [])
    .map(point => [
      Number(point.longitude),
      Number(point.latitude)
    ])
    .filter(coord =>
      Number.isFinite(coord[0]) &&
      Number.isFinite(coord[1])
    )
);

const routeSteps = instructions.map(instruction => ({
  name:
    instruction.street ||
    instruction.roadName ||
    instruction.routeNumbers?.join(", ") ||
    instruction.message ||
    "",

  distance_m:
    instruction.routeOffsetInMeters ?? null,

  duration_s:
    instruction.travelTimeInSeconds ?? null,

  instruction:
    instruction.combinedMessage ||
    instruction.message ||
    "",

  point_index:
    instruction.pointIndex ?? null,

  maneuver:
    instruction.maneuver || "",

  instruction_type:
    instruction.instructionType || ""
}));

function isUsefulStreetName(name) {
  const text = String(name || "").trim();
  const normalized = text.toLowerCase();

  if (!text || text === "-") return false;

  const genericManeuvers = [
    "leave",
    "turn right",
    "turn left",
    "bear right",
    "bear left",
    "keep right",
    "keep left",
    "go straight",
    "you have arrived",
    "arrive",
    "departure"
  ];

  if (genericManeuvers.some(term => normalized.includes(term))) {
    return false;
  }

  return true;
}

const streetNames = [
  ...new Set(
    routeSteps
      .map(step => step.name)
      .filter(isUsefulStreetName)
  )
];

const arrivalBufferMinutes =
  Number(destinationEvent.arrival_buffer_minutes || 0);

function addSeconds(dateValue, seconds) {
  const d = new Date(dateValue);
  if (Number.isNaN(d.getTime())) return null;

  d.setSeconds(d.getSeconds() + seconds);
  return d.toISOString();
}

function subtractSeconds(dateValue, seconds) {
  const d = new Date(dateValue);
  if (Number.isNaN(d.getTime())) return null;

  d.setSeconds(d.getSeconds() - seconds);
  return d.toISOString();
}

function isReturnHome(event) {
  return (
    event.task_type === "return_home" ||
    event.category === "return_home" ||
    event.title === "Return Home"
  );
}

let targetArrivalTime = null;
let suggestedDepartureTime = null;
let estimatedArrivalTime = null;

if (destinationEvent.start && durationSeconds !== null) {
  if (isReturnHome(destinationEvent)) {
    // For return home, do not arrive early.
    // The return-home event start acts as the departure time.
    suggestedDepartureTime = destinationEvent.start;

    estimatedArrivalTime = addSeconds(
      suggestedDepartureTime,
      durationSeconds
    );

    targetArrivalTime = estimatedArrivalTime;
  } else {
    // For normal events, arrive before the event by the configured buffer.
    targetArrivalTime = subtractSeconds(
      destinationEvent.start,
      arrivalBufferMinutes * 60
    );

    suggestedDepartureTime = subtractSeconds(
      targetArrivalTime,
      durationSeconds
    );

    estimatedArrivalTime = targetArrivalTime;
  }
}

return {
  json: {
