};

const routeData = $json;

const requestContext =
  $("BuildIntentInput").first().json;

const settings = requestContext.settings || {};

const routeDate =
  requestContext.route_date || null;

function formatRouteDate(dateValue) {
  if (!dateValue) {
    return null;
  }

  const parts =
    String(dateValue)
      .split("-")
      .map(Number);

  if (
    parts.length !== 3 ||
    parts.some(value => !Number.isFinite(value))
  ) {
    return null;
  }

  const [year, month, day] = parts;

  /*
   * Noon UTC prevents the date from shifting when it is
   * formatted in America/Toronto.
   */
  const date =
    new Date(
      Date.UTC(
        year,
        month - 1,
        day,
        12,
        0,
        0
      )
    );

  return date.toLocaleDateString("en-CA", {
    timeZone: "America/Toronto",
    weekday: "long",
    month: "long",
    day: "numeric"
  });
}

const routeDateLabel =
  formatRouteDate(routeDate);

function getOptionalNodeJson(nodeName) {
  try {
