  event.assigned_caregiver || "",

caregiver:
  event.caregiver || "",

driver:
  event.driver || "",

responsible_caregiver:
  event.responsible_caregiver || "",

visible_to:
  event.visible_to || [],

summary_visible_to:
  event.summary_visible_to || [],

passengers_in_vehicle:
  event.passengers_in_vehicle || [],

vehicle_only:
