function buildConstructionNote(leg, rerouteReason = "") {
  const impacts = leg.construction_impacts || [];

  if (!impacts.length) {
    return "No construction impact was reported for this trip.";
  }

  const relevantImpacts = impacts.filter(impact =>
    impact.is_relevant === true ||
    impact.exact_segment_overlap === true
  );

  const nearbyImpacts = impacts.filter(impact =>
    impact.is_relevant === false ||
    impact.exact_segment_overlap === false
  );

  if (relevantImpacts.length > 0) {
    const streets = [
      ...new Set(
        relevantImpacts
          .map(impact => impact.construction_street)
          .filter(Boolean)
      )
    ];

    return `Construction was confirmed on or directly affecting this route near ${streets.join(", ")}.`;
  }

  if (nearbyImpacts.length > 0) {
    const streets = [
      ...new Set(
        nearbyImpacts
          .map(impact => impact.construction_street)
          .filter(Boolean)
      )
    ];

    return `Nearby construction around ${streets.join(", ")} was checked, but it was not confirmed on the travelled street segment. ${rerouteReason || "The original route was kept."}`;
  }

  return leg.construction_summary || "No construction impact was reported for this trip.";
}

const fullScheduledEvents =
  routeData.ordered_events || [];

function normalizeKey(value) {
  return String(value || "")
    .toLowerCase()
    .trim();
}

function eventMatchKey(event = {}) {
  return [
    normalizeKey(event.title),
    normalizeKey(event.person),
    String(event.start || "")
  ].join("|");
}

const fullEventByKey = new Map();

for (const event of fullScheduledEvents) {
  fullEventByKey.set(eventMatchKey(event), event);
}

function enrichEventFromFullSchedule(event = {}) {
  const match =
    fullEventByKey.get(eventMatchKey(event));

  return {
    ...(match || {}),
    ...event,

    assigned_caregiver:
      event.assigned_caregiver ||
      match?.assigned_caregiver ||
      "",

    visible_to:
      event.visible_to?.length
        ? event.visible_to
        : match?.visible_to || [],

    summary_visible_to:
      event.summary_visible_to?.length
        ? event.summary_visible_to
        : match?.summary_visible_to || [],

    passengers_in_vehicle:
      event.passengers_in_vehicle?.length
        ? event.passengers_in_vehicle
        : match?.passengers_in_vehicle || [],

    vehicle_only:
      event.vehicle_only ??
      match?.vehicle_only ??
      false,

    autonomous_vehicle_task:
      event.autonomous_vehicle_task ??
      match?.autonomous_vehicle_task ??
      false
  };
}

const routeLegs = (routeData.route_legs || []).map(leg => ({
