  destination_vehicle_only: leg.destination_vehicle_only || false,

  mission_leg: leg.mission_leg !== false,

  route_steps: leg.route_steps || [],

  route_provider: leg.route_provider || "tomtom",

  distance_m: leg.distance_m ?? null,
  duration_s: leg.duration_s ?? null,
  duration_minutes:
