function normalizePerson(value) {
  return String(value || "").trim();
}

function includesPerson(values = [], person) {
  if (!Array.isArray(values)) return false;

  return values
    .map(normalizePerson)
    .includes(normalizePerson(person));
}

function isVehicleOnlyEvent(event = {}) {
  return (
    event.autonomous_vehicle_task === true ||
    event.vehicle_only === true ||
    ["charging", "service", "car_wash", "tire_change"].includes(event.task_type) ||
    ["charging", "service", "car_wash", "tire_change"].includes(event.category)
  );
}

function eventBelongsToActiveUser(event = {}) {
  if (!activePersonId) return false;

  const person = normalizePerson(event.person);

  const assignedCaregiver =
    normalizePerson(
      event.assigned_caregiver ||
      event.caregiver ||
      event.driver ||
      event.responsible_caregiver
    );

  if (person === activePersonId) {
    return true;
  }

  if (assignedCaregiver === activePersonId) {
    return true;
  }

  if (includesPerson(event.visible_to, activePersonId)) {
    return true;
  }

  return false;
}

function legShouldBeVisibleToActiveUser(leg = {}) {
  if (!activePersonId) return false;

  const destinationEvent = leg.destination_event || {};
  const startEvent = leg.start_event || {};
  const visibility = leg.route_visibility || {};

  if (
    leg.destination_vehicle_only === true ||
    isVehicleOnlyEvent(destinationEvent)
  ) {
    return false;
  }

  const assignedCaregiver =
    normalizePerson(
      destinationEvent.assigned_caregiver ||
      destinationEvent.caregiver ||
      destinationEvent.driver ||
      destinationEvent.responsible_caregiver
    );

  const destinationTaskType =
    normalizeKey(
      destinationEvent.task_type ||
      destinationEvent.event_type ||
      ""
    );

  const isAssignedPickup =
    destinationTaskType === "pickup" &&
    assignedCaregiver === normalizePerson(activePersonId);

  return (
    isAssignedPickup ||
    eventBelongsToActiveUser(destinationEvent) ||
    eventBelongsToActiveUser(startEvent) ||
    includesPerson(leg.passengers_in_vehicle || [], activePersonId) ||
    includesPerson(visibility.start_visible_to || [], activePersonId) ||
    includesPerson(visibility.end_visible_to || [], activePersonId) ||
    includesPerson(
      visibility.start_summary_visible_to || [],
      activePersonId
    ) ||
    includesPerson(
      visibility.end_summary_visible_to || [],
      activePersonId
    )
  );
}

function endpointVisibleToActiveUser(event = {}, visibilityList = []) {
  return (
    eventBelongsToActiveUser(event) ||
    includesPerson(visibilityList, activePersonId)
  );
}

function sameLocation(a = {}, b = {}) {
  const aLocation = normalizeKey(a.location || a.resolved_address || "");
  const bLocation = normalizeKey(b.location || b.resolved_address || "");

  if (aLocation && bLocation && aLocation === bLocation) {
    return true;
  }

  return false;
}

function findActiveUserEventAtLegDestination(leg = {}) {
  const destinationEvent = leg.destination_event || {};

  return fullScheduledEvents.find(event => {
    if (isVehicleOnlyEvent(event)) return false;

    if (!eventBelongsToActiveUser(event)) return false;

    return sameLocation(event, destinationEvent);
  });
}

function buildSharedRideNote(leg = {}) {
  const passengers =
    leg.passengers_in_vehicle || [];

  const otherPassengers =
    passengers.filter(
      person =>
        normalizePerson(person) !==
        normalizePerson(activePersonId)
    );

  const destinationEvent =
    leg.destination_event || {};

  const destinationTaskType =
    normalizeKey(
      destinationEvent.task_type ||
      destinationEvent.event_type ||
      ""
    );

  // A passenger being picked up is not already sharing the ride.
  // Suppress only the shared-ride note, not the route leg.
  if (destinationTaskType === "pickup") {
    return "";
  }

  const activeUserEventAtDestination =
    eventBelongsToActiveUser(destinationEvent)
      ? destinationEvent
      : findActiveUserEventAtLegDestination(leg);

  if (!includesPerson(passengers, activePersonId)) {
    return "";
  }

  if (!otherPassengers.length) {
    return "";
  }

  if (
    !destinationEvent.person ||
    destinationEvent.person === activePersonId
  ) {
    return "";
  }

  if (activeUserEventAtDestination) {
    return `You will ride with ${otherPassengers.join(", ")} while the vehicle first brings ${destinationEvent.person} to "${destinationEvent.title}". Your event "${activeUserEventAtDestination.title}" is at the same stop, so no extra driving leg is needed before your event.`;
  }

  return `You will ride with ${otherPassengers.join(", ")} while the vehicle first brings ${destinationEvent.person} to "${destinationEvent.title}".`;
}

function buildCaregiverResponsibilityNote(leg = {}) {
  const destinationEvent =
    leg.destination_event || {};

  const destinationTaskType =
    normalizeKey(
      destinationEvent.task_type ||
      destinationEvent.event_type ||
      ""
    );

  const assignedCaregiver =
    normalizePerson(
      destinationEvent.assigned_caregiver ||
      destinationEvent.caregiver ||
      destinationEvent.driver ||
      destinationEvent.responsible_caregiver
    );

  const dependent =
    destinationEvent.person || "";

  const isDependent =
    normalizeKey(destinationEvent.role) === "dependent";

  if (
    destinationTaskType !== "pickup" ||
    !isDependent ||
    assignedCaregiver !== normalizePerson(activePersonId)
  ) {
    return "";
  }

  return `${activePersonId} is responsible for picking up ${dependent}.`;
}

function sanitizeLegForActiveUser(leg = {}) {
  const visibility = leg.route_visibility || {};
const startEvent = leg.start_event || {};
const destinationEvent = leg.destination_event || {};

const activeUserEventAtDestination =
  eventBelongsToActiveUser(destinationEvent)
    ? destinationEvent
    : findActiveUserEventAtLegDestination(leg);

  const startVisible = endpointVisibleToActiveUser(
    startEvent,
    [
      ...(visibility.start_visible_to || []),
      ...(visibility.start_summary_visible_to || [])
    ]
  );

  const destinationVisible =
    eventBelongsToActiveUser(destinationEvent) ||
    !!activeUserEventAtDestination ||
    includesPerson(leg.passengers_in_vehicle || [], activePersonId);

  return {
    ...leg,

    start_address:
      startVisible
        ? leg.start_address
        : "Vehicle current location",

    end_address:
      destinationVisible
        ? leg.end_address
        : "Vehicle next household stop",

    active_user_related_event:
      activeUserEventAtDestination
        ? slimEvent(activeUserEventAtDestination)
        : null,

    shared_ride_note:
      buildSharedRideNote(leg),
    caregiver_responsibility_note:
  buildCaregiverResponsibilityNote(leg)
  };
}

const userRouteLegs = routeLegs
  .filter(legShouldBeVisibleToActiveUser)
  .map(sanitizeLegForActiveUser);

const userScheduledEvents = (routeData.ordered_events || [])
  .filter(event =>
    eventBelongsToActiveUser(event) &&
    !isVehicleOnlyEvent(event)
  )
  .map(slimEvent);

function formatTimeRange(start, end) {
  if (!start || !end) return "";

  const options = {
    timeZone: "America/Toronto",
    hour: "numeric",
    minute: "2-digit",
    hour12: true
  };

  const startText = new Date(start).toLocaleTimeString("en-CA", options);
  const endText = new Date(end).toLocaleTimeString("en-CA", options);

  return `${startText}–${endText}`;
}

function buildVehicleNote(routeData, chargingDecision, vehicleStatus) {
  if (!chargingDecision?.needs_charging) {
    return "";
  }

  const chargingEvent = (routeData.ordered_events || []).find(event =>
    event.autonomous_vehicle_task === true &&
    event.task_type === "charging"
  );

  const battery = vehicleStatus?.battery_percent;
  const preferred = chargingDecision.preferred_min_battery_percent;

  const batteryText =
    battery !== null && battery !== undefined && preferred !== null && preferred !== undefined
      ? `The car battery is ${battery}%, below the preferred minimum of ${preferred}%.`
      : "The car battery is below the preferred minimum.";

  if (chargingEvent) {
    const timeRange = formatTimeRange(chargingEvent.start, chargingEvent.end);

    return `${batteryText} The car will self-charge${timeRange ? ` from ${timeRange}` : ""} while you are at the meeting.`;
  }

  return `${batteryText} Charging is recommended, but no self-charging stop was scheduled from the available route data.`;
}

return [
