}

function severityForImpact(impact) {
  const candidate = impact.candidates || impact;

  const text = normalize([
    candidate.impact_type,
    candidate.impact_width,
    candidate.sidewalk,
    candidate.bikepath
  ].join(" "));

  if (
    text.includes("rue barree") ||
    text.includes("ferme") ||
    text.includes("closed") ||
    text.includes("blocked")
  ) {
    return "high";
  }

  if (
    text.includes("obstrue") ||
    text.includes("entrave") ||
    text.includes("voie") ||
    text.includes("lane") ||
    text.includes("sidewalk") ||
    text.includes("trottoir")
  ) {
    return "medium";
  }

  return "low";
}

function isDirectRouteStreetImpact(impact) {
  const candidate = impact.candidates || impact;

  const constructionStreet = normalize(candidate.construction_street);
  const matchedRouteStreet = normalize(candidate.matched_route_street);

  if (!constructionStreet || !matchedRouteStreet) {
    return false;
  }

  return (
    matchedRouteStreet.includes(constructionStreet) ||
    constructionStreet.includes(matchedRouteStreet)
  );
}

function polygonAroundRoutePoints(points, delta = 0.00035) {
  const valid = points
    .filter(p => Array.isArray(p) && p.length >= 2)
    .map(p => ({
      lng: Number(p[0]),
      lat: Number(p[1])
    }))
    .filter(p =>
      Number.isFinite(p.lng) &&
      Number.isFinite(p.lat)
    );

  if (valid.length === 0) {
    return null;
  }

  const lngs = valid.map(p => p.lng);
  const lats = valid.map(p => p.lat);

  const minLng = Math.min(...lngs) - delta;
  const maxLng = Math.max(...lngs) + delta;
  const minLat = Math.min(...lats) - delta;
  const maxLat = Math.max(...lats) + delta;

  const width = maxLng - minLng;
  const height = maxLat - minLat;

  // Safety check:
  // If the polygon is huge, it means we accidentally used the full route.
  // Do not send huge avoid polygons to OpenRouteService.
  if (width > 0.006 || height > 0.006) {
    return null;
  }

  return [[
    [minLng, minLat],
    [maxLng, minLat],
    [maxLng, maxLat],
    [minLng, maxLat],
    [minLng, minLat]
  ]];
}


function normalizeImpactText(value) {
  return String(value ?? "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .trim();
}

function requiresReroute(impact) {
  const streetImpact = normalizeImpactText(
    impact.street_impact_type ??
    impact.impact_type
  );

  if (
    !streetImpact ||
    streetImpact.includes("aucun impact") ||
    streetImpact.includes("non applicable")
  ) {
    return false;
  }

  const rerouteKeywords = [
    "barre",
    "rue fermee",
    "fermeture complete",
    "chaussee fermee",
    "voie de circulation fermee",
    "voie de circulation obstruee",
    "circulation interdite",
    "acces interdit",
    "route barree",
    "detour",
    "deviation",
    "circulation alternee",
    "reduction de voie",
  ];

  if (
    rerouteKeywords.some(keyword =>
      streetImpact.includes(keyword)
    )
  ) {
    return true;
  }

  // Parking-only impacts do not require rerouting.
  if (streetImpact.includes("stationnement")) {
    return false;
  }

  return false;
}

function severityForImpact(impact) {
  const streetImpact = normalizeImpactText(
    impact.street_impact_type ??
    impact.impact_type
  );

  if (
    streetImpact.includes("rue barree") ||
    streetImpact.includes("fermeture complete") ||
    streetImpact.includes("circulation interdite") ||
    streetImpact.includes("acces interdit")
  ) {
    return "high";
  }

  if (requiresReroute(impact)) {
    return "medium";
  }

  return "low";
}


