function haversineDistanceKm(from = {}, to = {}) {
  const fromLat = numberOrNull(from.lat);
  const fromLng = numberOrNull(from.lng);
  const toLat = numberOrNull(to.lat);
  const toLng = numberOrNull(to.lng);

  if (
    fromLat === null ||
    fromLng === null ||
    toLat === null ||
    toLng === null
  ) {
    return null;
  }

  const earthRadiusKm = 6371;
  const toRadians = degrees => degrees * Math.PI / 180;

  const deltaLat = toRadians(toLat - fromLat);
  const deltaLng = toRadians(toLng - fromLng);

  const lat1 = toRadians(fromLat);
  const lat2 = toRadians(toLat);

  const a =
    Math.sin(deltaLat / 2) ** 2 +
    Math.cos(lat1) *
      Math.cos(lat2) *
      Math.sin(deltaLng / 2) ** 2;

  return earthRadiusKm * 2 * Math.atan2(
    Math.sqrt(a),
    Math.sqrt(1 - a)
  );
}

function estimateUrbanTravelMinutes(from, to) {
  const straightLineDistanceKm =
    haversineDistanceKm(from, to);

  if (straightLineDistanceKm === null) {
    return null;
  }

  if (straightLineDistanceKm < 0.1) {
    return 0;
  }

  /*
   * Approximate road distance as 1.25 times straight-line
   * distance and use a conservative Montréal urban speed.
   */
  const roadDistanceKm =
    straightLineDistanceKm * 1.25;

  const estimatedSpeedKmh = 20;

  const drivingMinutes = Math.ceil(
    roadDistanceKm / estimatedSpeedKmh * 60
  );

  // Additional allowance for traffic, parking and entering/leaving.
  return Math.max(5, drivingMinutes + 5);
}

