  if (
    !chargingLocation ||
    chargingLocation.lat === null ||
    chargingLocation.lng === null
  ) {
    chargingGapEvaluations.push({
      current_event: currentEvent.title,
      next_event: nextEvent.title,
      accepted: false,
      reason: "Charging location has no valid coordinates."
    });

    continue;
  }

  const totalGapMinutes =
    minutesBetween(
      currentEvent.end,
      nextEvent.start
