    Math.min(
      defaultTaskMinutes,
      availableChargingMinutes
    );

  const accepted =
    totalGapMinutes >= minIdleMinutes &&
    availableChargingMinutes >= minTaskMinutes &&
    scheduledChargingMinutes >= minTaskMinutes;

  chargingGapEvaluations.push({
    current_event: currentEvent.title,
    next_event: nextEvent.title,

    total_gap_minutes:
