function clean(value) {
  if (value === null || value === undefined) return "";
  return String(value).trim();
}

function normalize(value) {
  return String(value || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[’']/g, "")
    .replace(/[^a-z0-9 ]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function isGenericLocation(location) {
  const text = normalize(location);

  if (!text) return true;

  return [
    "home",
    "house",
    "work",
    "office",
    "job",
    "school",
    "daycare",
    "child school",
    "kids school",
    "kid school"
  ].includes(text);
}

function looksLikeUsableAddress(value) {
  const text = clean(value);
  const normalized = normalize(text);

  if (!text) return false;
  if (text.length < 8) return false;
  if (isGenericLocation(text)) return false;

  const badValues = [
    "child1",
    "child2",
    "parent1",
    "parent2",
    "caregiver",
    "dependent",
    "school",
    "job",
    "work",
    "office"
  ];

  if (badValues.includes(normalized)) return false;

  return true;
}

function typeWords(type) {
  if (type === "school") {
    return [
      "school",
      "daycare",
      "pickup",
      "pick up",
      "dropoff",
      "drop off",
      "child"
    ];
  }

  if (type === "job") {
    return [
      "job",
      "work",
      "office",
      "employer",
      "research",
      "supervisor",
      "meeting",
      "workplace"
    ];
  }

  if (type === "home") {
    return [
      "home",
      "house"
    ];
  }

  return [];
}

function pathMatchesType(path, type) {
  const pathText = normalize(path);
  return typeWords(type).some(word => pathText.includes(normalize(word)));
}

function objectMatchesPerson(obj, person) {
  if (!person || !obj || typeof obj !== "object") return false;

  const normalizedPerson = normalize(person);

  const fields = [
    obj.person,
    obj.name,
    obj.id,
    obj.child,
    obj.caregiver,
    obj.owner,
    obj.role_name
  ];

  return fields.some(field => normalize(field) === normalizedPerson);
}

function pathMatchesPerson(path, person) {
  if (!person) return false;
  return normalize(path).includes(normalize(person));
}

function collectAddressCandidates(rootName, rootValue, type, person) {
  const candidates = [];

  function visit(value, path, context) {
    if (value === null || value === undefined) return;

    const currentPathText = normalize(path);

    const currentContext = {
      personMatched:
        context.personMatched ||
        pathMatchesPerson(path, person) ||
        objectMatchesPerson(value, person),

      typeMatched:
        context.typeMatched ||
        pathMatchesType(path, type)
    };

    if (typeof value === "string") {
      if (!looksLikeUsableAddress(value)) return;

      const score =
        (currentContext.personMatched ? 100 : 0) +
        (currentContext.typeMatched ? 50 : 0) +
        (currentPathText.includes("address") ? 25 : 0) +
        (currentPathText.includes("location") ? 25 : 0);

      candidates.push({
  address: clean(value),
  lat: context.lat ?? null,
  lng: context.lng ?? null,
  source: rootName + "." + path,
  score,
  personMatched: currentContext.personMatched,
  typeMatched: currentContext.typeMatched
});

      return;
    }

    if (Array.isArray(value)) {
      value.forEach((item, index) => {
        visit(item, `${path}[${index}]`, currentContext);
      });
      return;
    }

    if (typeof value === "object") {
      const objectLat =
      numberOrNull(value.lat) !== null
        ? numberOrNull(value.lat)
        : numberOrNull(value.latitude) !== null
          ? numberOrNull(value.latitude)
          : context.lat ?? null;

    const objectLng =
      numberOrNull(value.lng) !== null
        ? numberOrNull(value.lng)
        : numberOrNull(value.lon) !== null
          ? numberOrNull(value.lon)
          : numberOrNull(value.longitude) !== null
            ? numberOrNull(value.longitude)
            : context.lng ?? null;

  const objectContext = {
    ...currentContext,
    lat: objectLat,
    lng: objectLng
  };

  for (const [key, childValue] of Object.entries(value)) {
    visit(childValue, path ? `${path}.${key}` : key, objectContext);
  }
}
  }

  visit(rootValue, "", {
    personMatched: false,
    typeMatched: false
  });

  return candidates;
}

function findSavedAddress(type, person) {
  const allCandidates = [];

  for (const root of allSettingsRoots) {
    const candidates = collectAddressCandidates(
      root.name,
      root.value,
      type,
      person
    );

    allCandidates.push(...candidates);
  }

  let filteredCandidates = allCandidates;

  if (type !== "home" && person) {
    const personAndTypeMatches = filteredCandidates.filter(candidate => {
      return candidate.personMatched && candidate.typeMatched;
    });

    if (personAndTypeMatches.length > 0) {
      filteredCandidates = personAndTypeMatches;
    } else {
      const typeMatches = filteredCandidates.filter(candidate => {
        return candidate.typeMatched;
      });

      if (typeMatches.length > 0) {
        filteredCandidates = typeMatches;
      }
    }
  } else {
    const typeMatches = filteredCandidates.filter(candidate => {
      return candidate.typeMatched;
    });

    if (typeMatches.length > 0) {
      filteredCandidates = typeMatches;
    }
  }

  filteredCandidates.sort((a, b) => b.score - a.score);

  const best = filteredCandidates[0];

  if (!best) {
    return null;
  }

  return {
  address: best.address,
  lat: best.lat ?? null,
  lng: best.lng ?? null,
  source: best.source,
  debug_candidates: allCandidates
    .sort((a, b) => b.score - a.score)
    .slice(0, 10)
};
}

function inferFallbackLocation(event) {
  const title = normalize(event.title);
  const location = normalize(event.location);
  const role = normalize(event.role);
  const person = event.person;

  const looksLikeHome =
    location === "home" ||
    location === "house" ||
    title.includes("home") ||
    title.includes("return home");

  const looksLikeSchool =
    location.includes("school") ||
    location.includes("daycare") ||
    title.includes("school") ||
    title.includes("daycare") ||
    title.includes("pickup") ||
    title.includes("pick up") ||
    title.includes("dropoff") ||
    title.includes("drop off");

  const looksLikeWork =
    location.includes("work") ||
    location.includes("office") ||
    location.includes("job") ||
    title.includes("work") ||
    title.includes("office") ||
    title.includes("job") ||
    title.includes("research") ||
    title.includes("supervisor") ||
    title.includes("meeting");

  if (looksLikeHome) {
    return findSavedAddress("home", person);
  }

  if (looksLikeSchool || role === "dependent") {
    return findSavedAddress("school", person);
  }

  if (looksLikeWork) {
    return findSavedAddress("job", person);
  }

  return null;
}

const calendarEvents = rawEvents
