function normalize(value) {
  return String(value || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .trim();
}

function eventKey(event = {}) {
  return [
    normalize(event.person),
    normalize(event.title),
    String(event.start || "")
  ]
    .filter(Boolean)
    .join("|");
}

function inferCategory(event = {}) {
  const title = normalize(event.title);
  const role = normalize(event.role);

  if (
    role === "dependent" &&
    (
      title.includes("pickup") ||
      title.includes("pick up") ||
      title.includes("school") ||
      title.includes("daycare")
    )
  ) {
    return "school_pickup";
  }

  if (
    role === "dependent" &&
    (
      title.includes("soccer") ||
      title.includes("piano") ||
      title.includes("dance") ||
      title.includes("practice") ||
      title.includes("lesson") ||
      title.includes("game") ||
      title.includes("class")
    )
  ) {
    return "child_activity";
  }

  if (
    title.includes("doctor") ||
    title.includes("medical") ||
    title.includes("dentist") ||
    title.includes("appointment")
  ) {
    return "medical";
  }

  if (
    title.includes("work") ||
    title.includes("research") ||
    title.includes("meeting") ||
    title.includes("supervisor") ||
    title.includes("lab")
  ) {
    return "work";
  }

  return role === "dependent"
    ? "childcare"
    : "general";
}

function inferTaskType(event = {}) {
  const title = normalize(event.title);
  const role = normalize(event.role);
  const category = normalize(
    event.category || inferCategory(event)
  );

  if (
    title.includes("pickup") ||
    title.includes("pick up") ||
    category.includes("pickup")
  ) {
    return "pickup";
  }

  if (
    title.includes("dropoff") ||
    title.includes("drop off") ||
    category.includes("activity")
  ) {
    return "dropoff";
  }

  if (role === "dependent") {
    return "pickup";
  }

  return "event";
}

function inferPriority(event = {}) {
  const role = normalize(event.role);
  const category = normalize(
    event.category || inferCategory(event)
  );

  if (
    role === "dependent" &&
    (
      category.includes("school_pickup") ||
      category.includes("childcare") ||
      category.includes("medical")
    )
  ) {
    return 1;
  }

  if (
    role === "dependent" &&
    category.includes("child_activity")
  ) {
    return 2;
  }

  if (category.includes("medical")) {
    return 2;
  }

  if (
    category.includes("work") ||
    category.includes("research")
  ) {
    return 3;
  }

  return 5;
}

function inferArrivalBufferMinutes(event = {}) {
  const title = normalize(event.title);
  const category = normalize(event.category);
  const role = normalize(event.role);
  const taskType = normalize(event.task_type);

  const isDependent =
    role === "dependent";

  const isPickupOrDropoff =
    title.includes("pickup") ||
    title.includes("pick up") ||
    title.includes("school") ||
    title.includes("daycare") ||
    taskType.includes("pickup") ||
    taskType.includes("dropoff");

  const isChildActivity =
    category.includes("child_activity") ||
    title.includes("piano") ||
    title.includes("soccer") ||
    title.includes("dance") ||
    title.includes("practice") ||
    title.includes("recital") ||
    title.includes("lesson") ||
    title.includes("game") ||
    title.includes("class");

  const isMedical =
    category.includes("medical") ||
    title.includes("doctor") ||
    title.includes("medical") ||
    title.includes("dentist") ||
    title.includes("appointment");

  const isWork =
    category.includes("work") ||
    category.includes("research") ||
    title.includes("work") ||
    title.includes("research") ||
    title.includes("meeting") ||
    title.includes("supervisor") ||
    title.includes("lab");

  if (
    isDependent &&
    (isPickupOrDropoff || isChildActivity)
  ) {
    return childcareBuffer;
  }

  if (isMedical) {
    return medicalBuffer;
  }

  if (isWork) {
    return workBuffer;
  }

  return 0;
}

/**
 * Parses the AI agent output safely.
 *
 * Supports:
 * - Already-parsed objects
 * - Raw JSON strings
 * - JSON wrapped in ```json Markdown fences
 * - Explanatory text before or after the JSON
 */
function parseAgentOutput(rawOutput) {
  if (
    rawOutput === null ||
    rawOutput === undefined ||
    rawOutput === ""
  ) {
    return {};
  }

  if (typeof rawOutput === "object") {
    if (Array.isArray(rawOutput)) {
      return rawOutput[0] || {};
    }

    return rawOutput;
  }

  let text = String(rawOutput)
    .replace(/^\uFEFF/, "")
    .trim();

  // Remove a Markdown code fence when the entire
  // response is wrapped in one.
  text = text
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();

  try {
    const parsed = JSON.parse(text);

    if (typeof parsed === "string") {
      return parseAgentOutput(parsed);
    }

    if (Array.isArray(parsed)) {
      return parsed[0] || {};
    }

    return parsed || {};
  } catch (firstError) {
    // Fallback: extract the first complete-looking
    // JSON object from surrounding model commentary.
    const firstBrace = text.indexOf("{");
    const lastBrace = text.lastIndexOf("}");

    if (
      firstBrace !== -1 &&
      lastBrace > firstBrace
    ) {
      const jsonCandidate = text.slice(
        firstBrace,
        lastBrace + 1
      );

      try {
        const parsed = JSON.parse(jsonCandidate);

        if (typeof parsed === "string") {
          return parseAgentOutput(parsed);
        }

        if (Array.isArray(parsed)) {
          return parsed[0] || {};
        }

        return parsed || {};
      } catch (secondError) {
        throw new Error(
          "The route-planning agent returned invalid JSON " +
          "after Markdown fences were removed. " +
          `Output begins with: ${text.slice(0, 500)}`
        );
      }
    }

    throw new Error(
      "The route-planning agent output did not contain " +
      "a valid JSON object. " +
      `Output begins with: ${text.slice(0, 500)}`
    );
  }
}

