function localDateKey(value) {
  if (!value) {
    return null;
  }

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return null;
  }

  const parts =
    new Intl.DateTimeFormat("en-CA", {
      timeZone: "America/Toronto",
      year: "numeric",
      month: "2-digit",
      day: "2-digit"
    }).formatToParts(date);

  const year =
    parts.find(
      part => part.type === "year"
    )?.value;

  const month =
    parts.find(
      part => part.type === "month"
    )?.value;

  const day =
    parts.find(
      part => part.type === "day"
    )?.value;

  return `${year}-${month}-${day}`;
}

function roundUpToInterval(
  date,
  intervalMinutes = 15
) {
  const intervalMs =
    intervalMinutes *
    60 *
    1000;

  return new Date(
    Math.ceil(
      date.getTime() / intervalMs
    ) * intervalMs
  );
}

function isProtectedDependentPickup(
