  const role =
    normalize(event.role);

  const taskType =
    normalize(event.task_type);

  const category =
    normalize(event.category);

  const title =
    normalize(event.title);

  if (role !== "dependent") {
    return false;
  }

  return (
    taskType === "pickup" ||
    category.includes("school_pickup") ||
    category.includes("childcare") ||
    title.includes("pickup") ||
    title.includes("pick up") ||
    title.includes("school")
  );
}

