  if (impactLegName && namesMatch(impactLegName, leg.leg_name)) {
    return true;
  }

  // Fallback: match construction street to streets used by this leg
  const constructionStreet =
    impact.construction_street ||
    impact.street ||
    impact.street_name ||
    impact.road;

  const matchedRouteStreet =
    impact.matched_route_street ||
    impact.route_street ||
    impact.matched_street;

  const legStreetNames = leg.street_names || [];

  for (const street of legStreetNames) {
    if (
      namesMatch(constructionStreet, street) ||
      namesMatch(matchedRouteStreet, street)
    ) {
      return true;
    }
  }

  return false;
}

