  const area =
    impact.construction_street ||
    impact.street ||
    impact.street_name ||
    impact.road ||
    impact.location ||
    impact.matched_route_street;

  if (area) {
    return `possible nearby construction around ${area}`;
  }

  return "Possible nearby construction was found";
}

function routeDecisionText(hasImpacts) {
  if (!hasImpacts) {
    return "No construction impact was reported for this trip.";
