  if (selectedRoute === "rerouted") {
    return "A construction-aware route was selected for this trip.";
  }

  if (rerouteReason) {
    return `The original route was kept: ${rerouteReason}`;
  }

  return "The original route was kept because construction was not confirmed to block this driven trip.";
}

