  const constructionSummary =
  impactsForLeg.length > 0
    ? [...new Set(impactSummaries)].join("; ")
    : "No construction impact was reported for this trip.";

  return {
    ...leg,
    construction_impacts: impactsForLeg,
    construction_summary: constructionSummary
  };
});

