function includesActivePerson(values = []) {
  if (!Array.isArray(values)) return false;

  return values
    .map(normalize)
    .includes(activePersonKey);
}

function eventKey(event = {}) {
  return [
    event.original_event_id,
    event.title,
    event.start,
    event.person
