}

function isAutonomousVehicleTask(event = {}) {
  return (
    event.autonomous_vehicle_task === true ||
    event.vehicle_only === true ||
    ["charging", "service", "car_wash", "tire_change", "maintenance"].includes(event.task_type) ||
    ["charging", "service", "car_wash", "tire_change", "maintenance"].includes(event.category)
  );
}

function visibleToActiveUser(event = {}) {
  const explicitVisibleTo =
    event.visible_to ||
    event.visibleTo ||
    [];

  if (includesActivePerson(explicitVisibleTo)) {
    return true;
  }

  const eventPerson = normalize(event.person);
  const eventRole = normalize(event.role);

  // The active parent/person sees their own events.
  if (eventPerson && eventPerson === activePersonKey) {
    return true;
