  // Assigned caregiver can see dependent events assigned to them.
  const assignedCaregiver =
    normalize(
      event.assigned_caregiver ||
      event.caregiver ||
      event.driver ||
      event.responsible_caregiver
    );

  if (assignedCaregiver && assignedCaregiver === activePersonKey) {
    return true;
  }

  // Vehicle-only tasks should not appear as user route trips.
  if (isAutonomousVehicleTask(event)) {
