function legVisibleToActiveUser(leg = {}) {
  const destinationEvent =
    leg.destination_event || {};

  const activeUserRelatedEvent =
    leg.active_user_related_event || {};

  // Hide vehicle-only destination legs unless they are tied directly to the active user.
  if (
    isAutonomousVehicleTask(destinationEvent) &&
    !visibleToActiveUser(activeUserRelatedEvent) &&
    !includesActivePerson(leg.passengers_in_vehicle || []) &&
    !leg.shared_ride_note
