function buildUserSafeVehicleNote(data = {}) {
  const vehicleStatus =
    data.vehicle_status || {};

  const chargingDecision =
    data.charging_decision || {};

  const fullSchedule =
    data.full_vehicle_mission_plan?.scheduled_events || [];

  const chargingEvent =
    fullSchedule.find(event =>
      event.autonomous_vehicle_task === true &&
      (
        event.task_type === "charging" ||
        event.category === "charging" ||
        event.title === "Vehicle Self-Charging"
      )
    );

  if (!chargingDecision.needs_charging) {
    return data.vehicle_note || "";
  }

  const batteryPercent =
    vehicleStatus.battery_percent ??
    chargingDecision.battery_percent;

  const preferredMin =
    chargingDecision.preferred_min_battery_percent;

  if (chargingEvent?.start && chargingEvent?.end) {
    return `The car battery is ${batteryPercent}%, below the preferred minimum of ${preferredMin}%. The car will self-charge from ${formatTime12Hour(chargingEvent.start)}–${formatTime12Hour(chargingEvent.end)} during the available gap before your pickup.`;
  }

  return `The car battery is ${batteryPercent}%, below the preferred minimum of ${preferredMin}%. Charging is recommended, but no charging stop was scheduled from the available route data.`;
}

return [
