const instructionPattern =
  /^(turn|bear|keep|leave|continue|head|take|make|go|follow|enter|exit|you have arrived|arrive)$/i;

function normalizePoints(leg) {
  // Prepared structure: [{ lat, lng }]
  if (Array.isArray(leg.route_points)) {
    return leg.route_points
      .map(point => ({
        lat: Number(point.lat),
        lng: Number(point.lng),
      }))
      .filter(point =>
        Number.isFinite(point.lat) &&
        Number.isFinite(point.lng)
      );
  }

  // Original structure: [[lng, lat], [lng, lat], ...]
  if (Array.isArray(leg.geometry)) {
    return leg.geometry
      .filter(point =>
        Array.isArray(point) &&
        point.length >= 2
      )
      .map(point => ({
        lat: Number(point[1]),
        lng: Number(point[0]),
      }))
      .filter(point =>
        Number.isFinite(point.lat) &&
        Number.isFinite(point.lng)
      );
  }

  return [];
}

function calculateBoundingBox(points) {
  if (!points.length) {
    return null;
  }

  let minLat = Infinity;
  let maxLat = -Infinity;
  let minLng = Infinity;
  let maxLng = -Infinity;

  for (const point of points) {
    if (point.lat < minLat) minLat = point.lat;
    if (point.lat > maxLat) maxLat = point.lat;
    if (point.lng < minLng) minLng = point.lng;
    if (point.lng > maxLng) maxLng = point.lng;
  }

  return {
    min_lat: minLat,
    max_lat: maxLat,
    min_lng: minLng,
    max_lng: maxLng,
  };
}

function sampleRouteGeometry(
  points,
  maxPoints = 200
) {
  if (!Array.isArray(points) || points.length === 0) {
    return [];
  }

  const coordinates = points
    .map(point => [
      Number(point.lng),
      Number(point.lat),
    ])
    .filter(coordinate =>
      Number.isFinite(coordinate[0]) &&
      Number.isFinite(coordinate[1])
    );

  if (coordinates.length <= maxPoints) {
    return coordinates;
  }

  // Evenly sample the route while preserving the
  // first and last coordinates.
  return Array.from(
    { length: maxPoints },
    (_, sampleIndex) => {
      const sourceIndex = Math.round(
        sampleIndex *
        (coordinates.length - 1) /
        (maxPoints - 1)
      );

      return coordinates[sourceIndex];
    }
  );
}

function normalizeStreets(leg) {
  const sourceStreets = [
    ...(Array.isArray(leg.route_streets)
      ? leg.route_streets
      : []),

    ...(Array.isArray(leg.street_names)
      ? leg.street_names
      : []),
  ];

  return [
    ...new Set(
      sourceStreets
        .map(street => String(street).trim())
        .filter(Boolean)
        .filter(street => !instructionPattern.test(street))
        .filter(street =>
          !street.toLowerCase().startsWith(
            "you have arrived"
          )
        )
    ),
