    historicTrafficTravelTimeInSeconds:
      leg.historic_traffic_duration_s ?? null,

    trafficDelayInSeconds:
      leg.traffic_delay_s ?? null,

    trafficLengthInMeters:
      leg.traffic_length_m ?? null,
  };
}

