const allRouteStreets = [
  ...new Set(
    slimLegs.flatMap(leg => leg.route_streets)
  ),
];

return [
  {
    json: {
      route_legs: slimLegs,
      all_route_streets: allRouteStreets,
      route_legs_received: slimLegs.length,
      route_street_count: allRouteStreets.length,
    },
  },
];

const data = $input.first().json;

function asArray(value) {
  return Array.isArray(value) ? value : [];
}

function eventId(event = {}) {
  return String(
    event.original_event_id ||
    event.event_original_event_id ||
    event.related_calendar_event_id ||
    ""
  ).trim();
}

function timeMs(value) {
  if (!value) {
    return null;
  }

  const parsed = new Date(value).getTime();

  return Number.isFinite(parsed)
    ? parsed
    : null;
}

function uniquePeople(values = []) {
  return [
    ...new Set(
      asArray(values).filter(Boolean)
    )
  ];
}

function includesAll(actual = [], expected = []) {
  const actualSet = new Set(
    uniquePeople(actual)
  );

  return uniquePeople(expected).every(
    person => actualSet.has(person)
  );
}

const routeLegs =
  asArray(data.route_legs);

const assignments =
  asArray(data.caregiver_assignments);

const recommendations =
  asArray(data.reschedule_recommendations);

const updatedRecommendations =
  recommendations.map(recommendation => {
    const recommendationId = String(
      recommendation.event_original_event_id ||
      recommendation.original_event_id ||
      ""
    ).trim();

    const proposedStartMs =
      timeMs(recommendation.recommended_start);

    const proposedEndMs =
      timeMs(recommendation.recommended_end);

    /*
     * Find the final selected route entering the
     * proposed replacement appointment.
     */
    const inboundLeg = routeLegs.find(leg => {
      const destination =
        leg.destination_event || {};

      const destinationType = String(
        destination.task_type ||
        destination.event_type ||
        ""
      ).toLowerCase();

      return (
        recommendationId &&
        eventId(destination) === recommendationId &&
        destination.proposed_reschedule === true &&
        [
          "dropoff",
          "appointment"
        ].includes(destinationType)
      );
    });

    const destinationEvent =
      inboundLeg?.destination_event || {};

    const previousEvent =
      inboundLeg?.start_event || {};

    const previousEventEndMs =
      timeMs(previousEvent.end);

    const departureMs =
      timeMs(
        inboundLeg?.suggested_departure_time
      );

    const arrivalMs =
      timeMs(
        inboundLeg?.estimated_arrival_time
      );

    const destinationStartMs =
      timeMs(destinationEvent.start);

    const arrivalBufferMinutes = Number(
      inboundLeg?.arrival_buffer_minutes ??
      0
    );

    const requiredArrivalMs =
      proposedStartMs !== null
        ? proposedStartMs -
          arrivalBufferMinutes * 60_000
        : null;

    /*
     * Verify that the proposed appointment keeps
     * the original event duration.
     */
    const originalStartMs =
      timeMs(destinationEvent.original_start);

    const originalEndMs =
      timeMs(destinationEvent.original_end);

    /*
     * Required passengers are the caregiver plus
     * dependents assigned to that caregiver.
     */
    const expectedPassengers =
      uniquePeople([
        destinationEvent.person,

        ...assignments
          .filter(assignment => {
            return (
              String(
                assignment.assigned_caregiver ||
                ""
              ).toLowerCase() ===
                String(
                  destinationEvent.person ||
                  ""
                ).toLowerCase() &&

              String(
                assignment.role || ""
              ).toLowerCase() ===
                "dependent"
            );
          })
          .map(
            assignment => assignment.person
          )
      ]);

    const inboundPassengers =
      uniquePeople(
        inboundLeg?.passengers_in_vehicle ||
        destinationEvent.passengers_in_vehicle
      );

    /*
     * Find the route leaving the appointment.
     * This confirms that the remainder of the
     * household schedule is still routable.
     */
    const outboundLeg = routeLegs.find(leg => {
      const startEvent =
        leg.start_event || {};

      const startType = String(
        startEvent.task_type ||
        startEvent.event_type ||
        ""
      ).toLowerCase();

      return (
        recommendationId &&
        eventId(startEvent) ===
          recommendationId &&
        startType === "pickup"
      );
    });

    const outboundPassengers =
      uniquePeople(
        outboundLeg?.passengers_in_vehicle ||
        outboundLeg?.start_event
          ?.passengers_in_vehicle
      );

    const outboundDepartureMs =
      timeMs(
        outboundLeg?.suggested_departure_time
      );

    const checks = {
      proposed_time_present:
        proposedStartMs !== null &&
        proposedEndMs !== null &&
        proposedEndMs > proposedStartMs,

      inbound_route_found:
        Boolean(inboundLeg),

      destination_matches_proposal:
        proposedStartMs !== null &&
        destinationStartMs !== null &&
        Math.abs(
          destinationStartMs -
          proposedStartMs
        ) <= 60_000,

      previous_event_completed_before_departure:
        previousEventEndMs !== null &&
        departureMs !== null &&
        departureMs >= previousEventEndMs,

      arrival_buffer_preserved:
        arrivalMs !== null &&
        requiredArrivalMs !== null &&
        arrivalMs <=
          requiredArrivalMs + 1_000,

      original_duration_preserved:
        originalStartMs === null ||
        originalEndMs === null ||
        (
          proposedStartMs !== null &&
          proposedEndMs !== null &&
          Math.abs(
            (
              proposedEndMs -
              proposedStartMs
            ) -
            (
              originalEndMs -
              originalStartMs
            )
          ) <= 60_000
        ),

      required_passengers_preserved:
        expectedPassengers.length > 0 &&
        includesAll(
          inboundPassengers,
          expectedPassengers
        ),

      onward_route_found:
        Boolean(outboundLeg),

      onward_departure_after_appointment:
        proposedEndMs !== null &&
        outboundDepartureMs !== null &&
        outboundDepartureMs >=
          proposedEndMs,

      onward_passengers_preserved:
        expectedPassengers.length > 0 &&
        includesAll(
          outboundPassengers,
          expectedPassengers
        )
    };

    const feasibilityVerified =
      Object.values(checks).every(Boolean);

    const failedChecks =
      Object.entries(checks)
        .filter(([, passed]) => !passed)
        .map(([name]) => name);

    return {
      ...recommendation,

      feasibility_verified:
        feasibilityVerified,

      feasibility_validation: {
        checked_against:
          "final_selected_route",

        route_leg_name:
          inboundLeg?.leg_name || null,

        previous_event_end:
          previousEvent.end || null,

        suggested_departure_time:
          inboundLeg
            ?.suggested_departure_time ||
          null,

        estimated_arrival_time:
          inboundLeg
            ?.estimated_arrival_time ||
          null,

        required_arrival_time:
          requiredArrivalMs !== null
            ? new Date(
                requiredArrivalMs
              ).toISOString()
            : null,

        arrival_buffer_minutes:
          arrivalBufferMinutes,

        travel_duration_seconds:
          Number(
            inboundLeg?.duration_s ?? 0
          ) || null,

        expected_passengers:
          expectedPassengers,

        routed_passengers:
          inboundPassengers,

        onward_route_leg_name:
          outboundLeg?.leg_name || null,

        checks,

        failed_checks:
          failedChecks,

        reason:
          feasibilityVerified
            ? "The proposed time fits after the preceding pickup, preserves the arrival buffer and original duration, carries the required passengers, and has a valid onward route."
            : `The proposed time could not be fully verified: ${
                failedChecks.join(", ") ||
                "missing validation data"
              }.`
      }
    };
  });

/*
 * Update copies of the appointment stored inside
 * mission events and route legs.
 */
const verificationByEventId = new Map(
  updatedRecommendations.map(
    recommendation => [
      String(
        recommendation
          .event_original_event_id ||
        recommendation.original_event_id ||
        ""
      ).trim(),

      recommendation
        .feasibility_verified === true
    ]
  )
);

function updateEventVerification(event) {
  if (
    !event ||
    typeof event !== "object"
  ) {
    return event;
  }

  const id = eventId(event);

  if (
    !id ||
    !verificationByEventId.has(id)
  ) {
    return event;
  }

  return {
    ...event,

    feasibility_verified:
      verificationByEventId.get(id)
  };
}

return [
  {
    json: {
      ...data,

      reschedule_recommendations:
        updatedRecommendations,

      ordered_events:
        asArray(data.ordered_events).map(
          updateEventVerification
        ),

      routable_events:
        asArray(data.routable_events).map(
          updateEventVerification
        ),

      route_legs:
        routeLegs.map(leg => ({
          ...leg,

          start_event:
            updateEventVerification(
              leg.start_event
            ),

          destination_event:
            updateEventVerification(
              leg.destination_event
            )
        }))
    }
  }
];
